USE trabajos_grado_uts;
CREATE TABLE IF NOT EXISTS pqrs(id INT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL,tipo VARCHAR(20) NOT NULL,asunto VARCHAR(180) NOT NULL,descripcion TEXT NOT NULL,estado VARCHAR(30) NOT NULL DEFAULT 'ABIERTA',respuesta TEXT,fecha_respuesta DATETIME,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuario(id));
CREATE TABLE IF NOT EXISTS notificacion(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL,mensaje VARCHAR(500) NOT NULL,leida BOOLEAN DEFAULT FALSE,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuario(id));
CREATE TABLE IF NOT EXISTS documento(id INT AUTO_INCREMENT PRIMARY KEY,proyecto_id INT NOT NULL,tipo VARCHAR(40) NOT NULL,url VARCHAR(1000) NOT NULL,estado VARCHAR(30) NOT NULL DEFAULT 'PENDIENTE',observaciones TEXT,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(proyecto_id) REFERENCES proyecto(id));
CREATE TABLE IF NOT EXISTS pago(id INT AUTO_INCREMENT PRIMARY KEY,proyecto_id INT NOT NULL,tipo VARCHAR(60) NOT NULL,url VARCHAR(1000) NOT NULL,estado VARCHAR(30) NOT NULL DEFAULT 'PENDIENTE',observaciones TEXT,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(proyecto_id) REFERENCES proyecto(id));